SELECT ALL a FROM t;
SELECT DISTINCT a, b FROM t;
SELECT DISTINCT ON (a, b + 1) a, b, c FROM t ORDER BY a, b + 1, c DESC;
SELECT;
SELECT * FROM t WHERE a > 1 GROUP BY ALL a HAVING count(*) > 1;
SELECT a, count(*) FROM t GROUP BY DISTINCT ROLLUP (a, b), CUBE ((a, b), c);
SELECT a, b, sum(c) FROM t GROUP BY GROUPING SETS ((a), (b), (), (a, b));
SELECT a, b, sum(c) FROM t GROUP BY GROUPING SETS (a, ROLLUP (b, c), CUBE (d), GROUPING SETS (e, ()));
SELECT a, GROUPING(a, b) FROM t GROUP BY (), a, (b, c);
SELECT a, rank() OVER w, sum(b) OVER (w ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) FROM t WINDOW w AS (PARTITION BY c ORDER BY d), w2 AS (w);
SELECT sum(a) OVER (PARTITION BY b ORDER BY c RANGE BETWEEN '1 day'::interval PRECEDING AND '1 day'::interval FOLLOWING EXCLUDE CURRENT ROW) FROM t;
SELECT sum(a) OVER (ORDER BY c GROUPS BETWEEN 1 PRECEDING AND UNBOUNDED FOLLOWING EXCLUDE GROUP), sum(a) OVER (ROWS 2 PRECEDING EXCLUDE TIES), sum(a) OVER (ROWS UNBOUNDED PRECEDING EXCLUDE NO OTHERS) FROM t;
SELECT count(*) FILTER (WHERE a > 1) OVER (PARTITION BY b), array_agg(DISTINCT a ORDER BY a DESC NULLS LAST) FILTER (WHERE a IS NOT NULL) FROM t;
SELECT string_agg(a, ',' ORDER BY b USING >), percentile_cont(0.5) WITHIN GROUP (ORDER BY a), rank(3) WITHIN GROUP (ORDER BY a) FROM t;
SELECT a FROM t UNION SELECT b FROM u;
SELECT a FROM t UNION ALL SELECT b FROM u INTERSECT DISTINCT SELECT c FROM v EXCEPT ALL SELECT d FROM w;
(SELECT a FROM t ORDER BY a LIMIT 1) UNION (SELECT b FROM u) ORDER BY 1;
SELECT a FROM t ORDER BY a ASC, b DESC NULLS FIRST, c USING ~<~ NULLS LAST;
SELECT a FROM t LIMIT ALL;
SELECT a FROM t LIMIT 10 OFFSET 5;
SELECT a FROM t OFFSET 5 ROWS;
SELECT a FROM t OFFSET 1 ROW FETCH NEXT 3 ROWS ONLY;
SELECT a FROM t ORDER BY a FETCH FIRST ROW WITH TIES;
SELECT a FROM t ORDER BY a FETCH FIRST 5 ROWS WITH TIES;
SELECT a FROM t FOR UPDATE;
SELECT a FROM t FOR NO KEY UPDATE OF t NOWAIT;
SELECT a FROM t, u FOR SHARE OF t, u SKIP LOCKED FOR KEY SHARE OF u;
SELECT * FROM ONLY t x (a, b);
SELECT * FROM t AS x (a, b) TABLESAMPLE SYSTEM (10) REPEATABLE (42);
SELECT * FROM t TABLESAMPLE BERNOULLI (50.5);
SELECT * FROM LATERAL (SELECT 1) AS s (x);
SELECT * FROM t, LATERAL (SELECT * FROM u WHERE u.id = t.id) s;
SELECT * FROM generate_series(1, 10) WITH ORDINALITY AS g (v, n);
SELECT * FROM LATERAL unnest(ARRAY[1, 2]) u;
SELECT * FROM unnest(ARRAY[1, 2], ARRAY['a', 'b']) AS x (n, s);
SELECT * FROM f() AS (a int, b text);
SELECT * FROM f() AS t (a int, b text);
SELECT * FROM ROWS FROM (generate_series(1, 3), json_to_recordset('[{"a":1}]') AS (a int)) WITH ORDINALITY AS r (x, y, n);
SELECT * FROM a JOIN b ON a.id = b.id;
SELECT * FROM a INNER JOIN b USING (id);
SELECT * FROM a LEFT OUTER JOIN b USING (id, k) AS j;
SELECT * FROM a RIGHT JOIN b ON true;
SELECT * FROM a FULL OUTER JOIN b ON a.x = b.x AND a.y = b.y;
SELECT * FROM a NATURAL JOIN b;
SELECT * FROM a NATURAL LEFT JOIN b NATURAL FULL JOIN c;
SELECT * FROM a CROSS JOIN b;
SELECT * FROM (a JOIN b ON a.id = b.id) LEFT JOIN c ON c.id = a.id;
SELECT * FROM a JOIN (b JOIN c ON b.id = c.id) ON a.id = b.id;
SELECT * FROM a LEFT JOIN LATERAL (SELECT * FROM b WHERE b.a = a.id LIMIT 1) bb ON true;
WITH RECURSIVE t(n) AS (VALUES (1) UNION ALL SELECT n + 1 FROM t WHERE n < 100) SELECT sum(n) FROM t;
WITH w AS MATERIALIZED (SELECT 1), v AS NOT MATERIALIZED (SELECT 2) SELECT * FROM w, v;
WITH upd AS (UPDATE t SET a = 1 RETURNING *), del AS (DELETE FROM u RETURNING *), ins AS (INSERT INTO v VALUES (1) RETURNING *), m AS (MERGE INTO x USING y ON x.id = y.id WHEN MATCHED THEN DELETE RETURNING x.*) SELECT * FROM upd, del, ins, m;
WITH v (a, b) AS (VALUES (1, 2), (3, 4)) SELECT * FROM v;
TABLE t;
TABLE ONLY t;
TABLE t *;
SELECT a = b, a <> b, a != b, a < b, a > b, a <= b, a >= b FROM t;
SELECT a IS NULL, a IS NOT NULL, a ISNULL, a NOTNULL, a IS DISTINCT FROM b, a IS NOT DISTINCT FROM b FROM t;
SELECT a IS TRUE, a IS NOT TRUE, a IS FALSE, a IS NOT FALSE, a IS UNKNOWN, a IS NOT UNKNOWN FROM t;
SELECT a BETWEEN 1 AND 10, a NOT BETWEEN 1 AND 10, a BETWEEN SYMMETRIC 10 AND 1, a NOT BETWEEN SYMMETRIC 10 AND 1 FROM t;
SELECT a IN (1, 2, 3), a NOT IN (SELECT b FROM u), a = ANY (ARRAY[1, 2]), a = SOME (SELECT b FROM u), a > ALL (SELECT b FROM u) FROM t;
SELECT EXISTS (SELECT 1 FROM u), NOT EXISTS (SELECT 1 FROM v) FROM t;
SELECT (a, b) = (1, 2), ROW(a, b) < ROW(c, d), (a, b) IS DISTINCT FROM (c, d), ROW(a, b) IN (SELECT c, d FROM u) FROM t;
SELECT s LIKE 'a%', s NOT LIKE 'a%' ESCAPE '!', s ILIKE 'A%', s NOT ILIKE 'b%', s SIMILAR TO '%(b|d)%', s NOT SIMILAR TO 'x' ESCAPE '#' FROM t;
