SELECT s COLLATE "C", s COLLATE pg_catalog."default" < 'b', (s || 't') COLLATE "de_DE" FROM t;
SELECT ts AT TIME ZONE 'UTC', ts AT TIME ZONE INTERVAL '-08:00', ts AT LOCAL, (ts AT TIME ZONE 'UTC') AT TIME ZONE 'Asia/Tokyo' FROM t;
