SELECT a + b, a - b, a * b, a / b, a % b, a ^ b, |/ a, ||/ a, @ a, a & b, a | b, a # b, ~ a, a << 1, a >> 1, - a, + a FROM t;
SELECT -1, - - 1, -(-1), 2 - -1, 1 - +1, -x.a FROM t x;
SELECT arr[1], arr[1:2], arr[:2], arr[2:], arr[1][2], (arr)[1], (f(x))[1], (row_col).field, (row_col).*, (SELECT ARRAY[1, 2])[1] FROM t;
