SELECT coalesce(a, b, 0), nullif(a, 0), greatest(a, b), least(a, b) FROM t;
SELECT CAST(a AS text), a::text, a::numeric(10, 2), a::varchar(10)[], a::double precision, a::timestamp with time zone, a::timestamp(3) without time zone, a::interval day to second(3), a::bit varying(8), a::character varying(5), a::"MyType", a::pg_catalog.int4, a::public.mytype[] FROM t;
