SELECT j -> 'a', j ->> 'a', j #> '{a,b}', j #>> '{a,b}', j @> '{"a":1}', j <@ '{"a":1}', j ? 'a', j ?| ARRAY['a', 'b'], j ?& ARRAY['a'], j || '{}', j - 'a', j #- '{a}', j @? '$.a', j @@ '$.a == 1' FROM t;
